
CREATE TABLE "EWALLET_V21"."ACCESS_LOG" 
   (	"ID" NUMBER(19,0) NOT NULL ENABLE, 
	"ACTION_ID" VARCHAR2(255 CHAR), 
	"CORE_TRANSACTION_ID" VARCHAR2(255 CHAR), 
	"CREATED_DATE" TIMESTAMP (6), 
	"DIRECTION" NUMBER(10,0), 
	"REF_TRANS_ID" VARCHAR2(255 CHAR), 
	"REQUEST_CONTENT" VARCHAR2(255 CHAR), 
	"RESPONSE_CODE" VARCHAR2(255 CHAR), 
	"RESPONSE_CONTENT" VARCHAR2(2000 CHAR), 
	 PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "DATA"  ENABLE
   ) SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "DATA" ;

CREATE UNIQUE INDEX "EWALLET_V21"."SYS_C0020731" ON "EWALLET_V21"."ACCESS_LOG" ("ID") 
  PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "DATA" ;

GRANT SELECT ON "EWALLET_V21"."ACCESS_LOG" TO "VTL_SELECT";
;

CREATE TABLE "EWALLET_V21"."ACCOUNT" 
   (	"ACCOUNT_ID" NUMBER(12,0) NOT NULL ENABLE, 
	"PAN" VARCHAR2(34), 
	"ACCOUNT_STATE_ID" NUMBER(5,0) NOT NULL ENABLE, 
	"BALANCE" RAW(2000), 
	"ACCOUNT_TYPE_ID" NUMBER(5,0) NOT NULL ENABLE, 
	"MODIFIED_DATE" TIMESTAMP (7), 
