	  REFERENCES "EWALLET_V21"."ACCOUNT_STATE" ("ACCOUNT_STATE_ID") ENABLE;
  ALTER TABLE "EWALLET_V21"."ACCOUNT" ADD CONSTRAINT "FK_AT_ATE" FOREIGN KEY ("ACCOUNT_TYPE_ID")
	  REFERENCES "EWALLET_V21"."ACCOUNT_TYPE" ("ACCOUNT_TYPE_ID") ENABLE;
  ALTER TABLE "EWALLET_V21"."ACCOUNT" ADD CONSTRAINT "FK_AT_CY" FOREIGN KEY ("CURRENCY_ID")
	  REFERENCES "EWALLET_V21"."CURRENCY" ("CURRENCY_ID") ENABLE;
  ALTER TABLE "EWALLET_V21"."ACCOUNT" ADD CONSTRAINT "FK_AT_PRE" FOREIGN KEY ("PARTY_ROLE_ID")
	  REFERENCES "EWALLET_V21"."PARTY_ROLE" ("PARTY_ROLE_ID") ENABLE;

