COMMENT ON COLUMN EWALLET_V21.ACCOUNT.ACCOUNT_ID IS 'ID Tai khoan';
COMMENT ON COLUMN EWALLET_V21.ACCOUNT.PAN IS 'So tai khoan';
COMMENT ON COLUMN EWALLET_V21.ACCOUNT.ACCOUNT_STATE_ID IS 'ID trang thai tai khoan, FK account_state';
COMMENT ON COLUMN EWALLET_V21.ACCOUNT.BALANCE IS 'So du';
COMMENT ON COLUMN EWALLET_V21.ACCOUNT.ACCOUNT_TYPE_ID IS 'ID loai tai khoan, FB ACCOUNT_TYPE';
COMMENT ON COLUMN EWALLET_V21.ACCOUNT.CURRENCY_ID IS 'Ma tien te FK Currency';
COMMENT ON COLUMN EWALLET_V21.ACCOUNT.VPAN IS 'Verify pan';
COMMENT ON COLUMN EWALLET_V21.ACCOUNT.LAST_RESET_PIN IS 'Thoi diem yeu cau reset pin gan nhat';
COMMENT ON COLUMN EWALLET_V21.ACCOUNT.IS_CURRENT IS 'La tai khoan mac dinh';
COMMENT ON COLUMN EWALLET_V21.ACCOUNT.COUNT_QUERY_CASH IS 'So lan truy van lien tiep, giao dich giao tien mat';
COMMENT ON COLUMN EWALLET_V21.ACCOUNT.ACTIVE_TIME IS 'Thoi gian kich hoat';
COMMENT ON COLUMN EWALLET_V21.ACCOUNT.LAST_TRANS_TIME IS 'Thoi gian giao dich gan nhat';
COMMENT ON COLUMN EWALLET_V21.ACCOUNT.LAST_CHANGE_BALANCE_TIME IS 'Thoi gian giao dich thay doi so du gan nhat';
COMMENT ON COLUMN EWALLET_V21.ACCOUNT.RE_ACTIVE_TIME IS 'Thoi diem kich hoat lại tk';

CREATE TABLE "EWALLET_V21"."ACCOUNT_1" 
   (	"ACCOUNT_ID" NUMBER(12,0) NOT NULL ENABLE, 
	"PAN" VARCHAR2(34), 
	"ACCOUNT_STATE_ID" NUMBER(5,0) NOT NULL ENABLE, 
