CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."ACCOUNT_INFO_VIEW" ("MSISDN", "PAN", "ACCOUNT_TYPE_ID", "ACCOUNT_ID", "CURRENCY_ID", "CURRENCY_CODE", "CURRENCY", "PARTY_ID", "PARTY_NAME", "ROLE_ID", "ROLE_NAME", "ACCOUNT_TYPE_NAME", "PAPER_TYPE", "PAPER_NUMBER", "PAPER_NAME") AS 
  (
SELECT   tb2."MSISDN",tb2."PAN",tb2."ACCOUNT_TYPE_ID",tb2."ACCOUNT_ID",tb2."CURRENCY_ID",tb2."CURRENCY_CODE",tb2."CURRENCY",tb2."PARTY_ID",tb2."PARTY_NAME",tb2."ROLE_ID",tb2."ROLE_NAME",tb2."ACCOUNT_TYPE_NAME",tb2."PAPER_TYPE",tb2."PAPER_NUMBER",
         pt.paper_name
  FROM       (SELECT   tb1.*,
                       ate.name account_type_name,
                       pp.paper_type,
                       pp.paper_number
                FROM           (SELECT   pr.msisdn msisdn,
                                         ac.pan pan,
                                         ac.account_type_id,
                                         ac.account_id,
                                         ac.currency_id,
                                         c.currency_code,
                                         c.currency,
                                         p.party_id,
                                         p.given_name party_name,
                                         r.role_id,
                                         r.name role_name,
                                         pr.party_paper_id
                                  FROM               party_role pr
                                                 LEFT JOIN
                                                     party p
                                                 ON pr.party_id = p.party_id
                                             LEFT JOIN
                                                 roles r
                                             ON r.role_id = pr.role_id
                                         LEFT JOIN
                                             account ac
                                             LEFT JOIN 
                                                currency c
                                             ON ac.currency_id = c.currency_id
                                             AND c.used IS NOT NULL
                                         ON pr.party_role_id =
                                                ac.party_role_id) tb1
                           LEFT JOIN
                               account_type ate
                           ON tb1.account_type_id = ate.account_type_id
                       LEFT JOIN
                           party_paper pp
                       --ON pp.party_id = tb1.party_id) tb2
                        ON pp.paper_id = tb1.party_paper_id) tb2
         LEFT JOIN
             paper_type pt
         ON tb2.paper_type = pt.paper_type
);

