CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."ACCOUNT_STATUS_VIEW" ("ACCOUNT_ID", "CODE", "ROLE_ID", "ROLE_NAME", "PARTY_ROLE_ID", "PARTY_ID", "FIRST_NAME", "LAST_NAME", "GENDER", "BIRTHDAY", "TIN", "ADDRESS", "AREA_CODE", "MSISDN", "CURRENCY_CODE", "PAPER_TYPE", "PAPER_NUMBER", "ISSUED_DATE", "ISSUED_PLACE", "EXPIRED_DATE", "ACCOUNT_STATE_ID", "ACCOUNT_STATE_NAME", "ACCOUNT_TYPE_ID", "ACCOUNT_TYPE_NAME", "PAPER_NAME", "ACTIVE_TIME", "DISTRINCT", "SUBDISTRICT", "SUKU") AS 
  SELECT b.account_id,
  ag.code,
  b.role_id,
  b.role_name,
  b.party_role_id,
  a.party_id,
  a.first_name AS first_name,
  a.given_name  AS last_name,
  a.gender,
  a.birthday,
  a.tin,
  a.address,
  a.area_code,
  b.msisdn,
  b.currency_code,
  c.paper_type,
  c.paper_number,
  c.issued_date,
  c.issued_place,
  c.expired_date,
  b.account_state_id,
  b.account_state_name,
  b.account_type_id,
  b.account_type_name,
  d.paper_name,
  b.active_time,
  dis.area_name distrinct,
  subdis.area_name subdistrict,
  suku.area_name suku
FROM party a
INNER JOIN
  (SELECT grole.role_id,
    grole.name AS role_name,
    prole.party_id,
    prole.msisdn,
    prole.party_paper_id,
    ac.*
  FROM party_role prole,
    roles grole,
    (SELECT account.account_id,
      account.pan,
      account.pin,
      account.vpan,
      account.account_state_id,
      astate.name AS account_state_name,
      account.account_type_id, 
      atype.name AS account_type_name,
      account.party_role_id,
      account.partition_key,
      PKG_CRYPTO_UTIL.DECRYPT_BALANCE('account',account.account_id,1) balance,
      PKG_CRYPTO_UTIL.DECRYPT_BALANCE('account',account.account_id,2) holding_balance,
      PKG_CRYPTO_UTIL.DECRYPT_BALANCE('account',account.account_id,3) available_balance,
      account.currency_id,
      currency.currency,
      currency.currency_code,
      currency.currency_num_code,
      currency.minor_unit,
      account.active_time
    FROM account account,
      currency currency,
      account_state astate,
      account_type atype
    WHERE account.currency_id    = currency.currency_id
    AND account.account_state_id = astate.account_state_id
    AND account.account_type_id  = atype.account_type_id
    AND account.account_state_id <> -1
    ) ac
  WHERE prole.role_id     = grole.role_id
  AND prole.status =1
  AND (prole.valid_from is null or prole.valid_from <= sysdate)
  AND (prole.valid_to is null or prole.valid_to >= sysdate)
  AND prole.party_role_id = ac.party_role_id
  ) b
ON a.party_id = b.party_id
INNER JOIN party_paper c
ON b.party_paper_id = c.paper_id
AND c.status  > 0
INNER JOIN paper_type d
ON c.paper_type = d.paper_type
LEFT JOIN agent ag on ag.party_role_id = b.party_role_id and ag.status =1
LEFT JOIN AREA dis on dis.area_code = substr(a.area_code,1,3) 
LEFT JOIN AREA subdis on subdis.area_code = substr(a.area_code,1,5) 
LEFT JOIN AREA suku on suku.area_code = a.area_code;

GRANT SELECT ON "EWALLET_V21"."ACCOUNT_STATUS_VIEW" TO "VTL_SELECT";
  GRANT SELECT ON "EWALLET_V21"."ACCOUNT_STATUS_VIEW" TO "ITREPORT";
;

