CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."AGENT_ACCOUNT_STATE_VIEW" ("AGENT_ID", "PARTY_ROLE_ID", "ACCOUNT_STATE_ID", "NAME_STATE") AS 
  SELECT             a.agent_id,
                   a.party_role_id,
                   b.account_state_id,
                   c.name name_State
            FROM agent a
                       INNER JOIN
                              account b
                       ON a.party_role_id = b.party_role_id
                   INNER JOIN
                       account_state c
                   ON b.account_state_id = c.account_state_id;

