CREATE TABLE "EWALLET_V21"."LOG_TRANS_SUMMARY_BY_RANGE" 
   (	"LOG_DATE" DATE NOT NULL ENABLE, 
	"INSERT_DATE" DATE NOT NULL ENABLE, 
	"CARRIED_ACC_ID" NUMBER, 
	"CARRIED_PHONE" VARCHAR2(19), 
	"CARRIED_ROLE_ID" NUMBER(2,0), 
	"CARRIED_PROVINCE" VARCHAR2(9), 
	"CARRIED_DISTRICT" VARCHAR2(9), 
	"CARRIED_AREA" VARCHAR2(20), 
	"TO_ACC_ID" NUMBER, 
	"TO_PHONE" VARCHAR2(19), 
	"TO_ROLE_ID" NUMBER(2,0), 
	"TO_PROVINCE" VARCHAR2(9), 
	"TO_DISTRICT" VARCHAR2(9), 
	"TO_AREA" VARCHAR2(20), 
