CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."MSSI_CUS_INFOR_VIEW" ("CUS_PHONE", "NEW_PHONE", "AMOUNT", "CUS_NAME", "PAPER_NUMBER", "MODIFIED_BY", "CREATED_DATE", "MODIFIED_DATE", "DISTRICT", "HEALTH_POST", "VERIFY_STATUS", "PAYMENT_STATUS", "STATUS_CASHOUT", "NOTE", "REVIEW_NODE", "REVIEW_TYPE", "STAGE") AS 
  (
                     select cus_phone, new_phone , amount, cus_name , paper_number ,modified_by , created_date , modified_date , 
                     district , health_post , STATUS verify_status, DECODE(STATUS, 1, 1, 0) payment_status ,
                     STATUS_CASHOUT ,note, review_node ,review_type , stage  from mssi_cus_infor union 
                     select a.cus_phone, a.new_phone , b.amount, a.cus_name , a.paper_number ,a.modified_by , a.created_date , a.modified_date , 
                     a.district , a.health_post ,a.status verify_status, b.STATUS payment_status, b.STATUS_CASHOUT ,a.note, a.review_node ,a.review_type , a.stage  
                     from mssi_cus_infor_payment b join MSSI_CUS_INFOR a on b.cus_phone = a.cus_phone);
;

