CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."RP_DAILY_AUDIT_VIEW" ("ACCOUNT_ID", "CODE", "NAME", "DEBIT", "CREDIT", "DATE_AUDIT", "BALANCE", "CURRENCY_ID") AS 
  (
  select v."ACCOUNT_ID",v."CODE",v."NAME",v."DEBIT",v."CREDIT",v."DATE_AUDIT",v."BALANCE", mas.CURRENCY_ID from (SELECT rp.account_id,
  rp.code,
  rp.name,
  t.debit,
  t.credit,
  rp.date_audit,
  rp.balance
FROM rp_daily_audit rp
LEFT JOIN
  (SELECT SUM(debit) debit,
    SUM(credit) credit,
    account_id
  FROM rp_daily_audit
  WHERE account_id IN
    (SELECT account_id FROM master_account
    )
  GROUP BY account_id
  ORDER BY account_id DESC
  ) t
ON rp.account_id = t.account_id) v LEFT JOIN
MASTER_ACCOUNT mas on mas.account_id = v.account_id
);

GRANT SELECT ON "EWALLET_V21"."RP_DAILY_AUDIT_VIEW" TO "VTL_SELECT";
  GRANT SELECT ON "EWALLET_V21"."RP_DAILY_AUDIT_VIEW" TO "ITREPORT";
;

