CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."RP_EXPORT_DAILY_AUDIT_VIEW" ("CODE", "NAME", "DEBIT", "CREDIT", "ACCOUNT_ID", "CURRENCY_ID", "DATE_AUDIT_BEGIN", "DATE_AUDIT_END", "BALANCE_BEGIN", "BALANCE_END") AS 
  (SELECT t0.code,
    t0.name,
    t0.debit,
    t0.credit,
    t0.account_id,
    t0.currency_id,
    t0.date_audit date_audit_begin,
    t1.date_audit date_audit_end,
    t0.balance balance_begin,
    t1.balance balance_end
  FROM
    (SELECT r.*
    FROM rp_daily_audit_view r
    INNER JOIN
      (SELECT code,
        MIN(date_audit) date_audit
      FROM rp_daily_audit_view
      GROUP BY code
      ) min_date
    ON r.code        = min_date.code
    AND r.date_audit = min_date.date_audit
    ) t0
  LEFT JOIN
    (SELECT r.*
    FROM rp_daily_audit_view r
    INNER JOIN
      (SELECT code,
        MAX(date_audit) date_audit
      FROM rp_daily_audit_view
      GROUP BY code
      ) max_date
    ON r.code        = max_date.code
    AND r.date_audit = max_date.date_audit
    ) t1 ON t0.code  = t1.code
  );

GRANT SELECT ON "EWALLET_V21"."RP_EXPORT_DAILY_AUDIT_VIEW" TO "VTL_SELECT";
  GRANT SELECT ON "EWALLET_V21"."RP_EXPORT_DAILY_AUDIT_VIEW" TO "ITREPORT";
;

