	"DATE_CREATED" DATE NOT NULL ENABLE, 
	"ACCOUNT_ID" NUMBER, 
	"ROLE_ID" NUMBER(2,0), 
	"CODE" VARCHAR2(20), 
	"PHONE" VARCHAR2(20), 
	"NAME" VARCHAR2(100), 
	"AGENT_ACC_ID" NUMBER, 
	"AGENT_CODE" VARCHAR2(10), 
	"AGENT_PHONE" VARCHAR2(20), 
	"AGENT_NAME" VARCHAR2(100), 
	"AREA_CODE" VARCHAR2(10), 
	"AREA_NAME" VARCHAR2(100), 
	"COUNTRY" VARCHAR2(20), 
	"COUNTRY_NAME" VARCHAR2(100), 
	"PROVINCE" VARCHAR2(20), 
	"PROVINCE_NAME" VARCHAR2(100), 
