	"DISTRICT_NAME" VARCHAR2(100), 
	"SUB_DISTRICT" VARCHAR2(20), 
	"SUB_DISTRICT_NAME" VARCHAR2(100), 
	"WARD" VARCHAR2(20), 
	"WARD_NAME" VARCHAR2(100), 
	"ADDRESS" VARCHAR2(200), 
