CREATE OR REPLACE EDITIONABLE TRIGGER "EWALLET_V21"."tb_changes_capture_transaction" 
after DELETE OR INSERT OR UPDATE ON TRANSACTION 
REFERENCING OLD AS OLD NEW AS NEW 
FOR EACH ROW   
begin   

    BEGIN
       INSERT INTO LOG_TABLE_CHANGES_CAPTURE (TABLE_NAME, ID_COLUMN_VALUE, ID_COLUMN_NAME, DATE_MODIFIER, DESCRIPTION, STATUS_RECORD)
        VALUES ('TRANSACTION', :NEW.transaction_id
        , 'TRANSACTION_ID', SYSTIMESTAMP , 'STATUS : '||:OLD.TRANSACTION_STATE_ID||' -> '||:NEW.TRANSACTION_STATE_ID
        , :NEW.TRANSACTION_STATE_ID
        );
     EXCEPTION
    WHEN OTHERS
                THEN
         record_error ();
     END;

end;

/
ALTER TRIGGER "EWALLET_V21"."tb_changes_capture_transaction" ENABLE;

