CREATE OR REPLACE EDITIONABLE TRIGGER "EWALLET_V21"."TRG_CHANGE_PAYMENT_STATUS_COM" 
after update of PAYMENT_STATUS on TRANS_COMMISSION 
REFERENCING OLD AS OLD NEW AS NEW 
FOR EACH ROW   WHEN (OLD.PAYMENT_STATUS = 0 and NEW.PAYMENT_STATUS IN (1,2)) begin   

  UPDATE LOG_TRANS_COMMISSION
     SET PAYMENT_STATUS = :NEW.PAYMENT_STATUS,
         COMMISSION_DATE = SYSDATE,
         COMMISSION_DATE_INT = F_CONVERT_DATE_TO_NUMBER(SYSDATE)
   WHERE TRANS_COMMISSION_ID = :NEW.TRANS_COMMISSION_ID
;
end;
/
ALTER TRIGGER "EWALLET_V21"."TRG_CHANGE_PAYMENT_STATUS_COM" ENABLE;

