CREATE OR REPLACE EDITIONABLE TRIGGER "EWALLET_V21"."tb_changes_capture_trans_step" 
after DELETE OR INSERT OR UPDATE ON TRANS_STEP 
REFERENCING OLD AS OLD NEW AS NEW 
FOR EACH ROW   
begin   

    BEGIN
       INSERT INTO LOG_TABLE_CHANGES_CAPTURE (TABLE_NAME, ID_COLUMN_VALUE, ID_COLUMN_NAME, DATE_MODIFIER, DESCRIPTION, STATUS_RECORD)
        VALUES ('TRANS_STEP', :NEW.ID, 'ID', SYSTIMESTAMP 
        ,'TRANSACTION_ID : '|| :NEW.TRANSACTION_ID || ', STATUS : '||:NEW.BEFORE_TRANS_STATE_ID||' -> '||:NEW.AFTER_TRANS_STATE_ID
        , :NEW.TRANS_STEP_STATE_ID
        );
     EXCEPTION
    WHEN OTHERS
                THEN
         record_error ();
     END;

end;
/
