CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."VIEW_ACCOUNT_AREA" ("ACCOUNT_ID", "CODE", "ROLE_ID", "ROLE_NAME", "PARTY_ROLE_ID", "PARTY_ID", "LAST_NAME", "GENDER", "BIRTHDAY", "ADDRESS", "AREA_CODE", "MSISDN", "PAPER_TYPE", "PAPER_NUMBER", "ISSUED_DATE", "ISSUED_PLACE", "EXPIRED_DATE", "ACCOUNT_STATE_ID", "ACCOUNT_STATE_NAME", "ACCOUNT_TYPE_ID", "ACCOUNT_TYPE_NAME", "PAPER_NAME", "ACTIVE_TIME", "DISTRINCT", "SUBDISTRICT", "SUKU") AS 
  SELECT b.account_id,
  nvl(ag.code,ag1.code) code,
  b.role_id,
  b.role_name,
  b.party_role_id,
  a.party_id,
  a.given_name  AS last_name,
  a.gender,
  a.birthday,
  a.address,
  nvl(a.area_code,ag1.area_code) area_code,
  b.msisdn,
  c.paper_type,
  c.paper_number,
  c.issued_date,
  c.issued_place,
  c.expired_date,
  b.account_state_id,
  b.account_state_name,
  b.account_type_id,
  b.account_type_name,
  d.paper_name,
  b.active_time,
  nvl(dis.area_name,dis1.area_name) distrinct,
  nvl(subdis.area_name,subdis1.area_name) subdistrict,
  nvl(suku.area_name,suku1.area_name) suku
FROM party a
INNER JOIN
  (SELECT grole.role_id,
    grole.name AS role_name,
    prole.party_id,
    prole.msisdn,
    prole.party_paper_id,
    ac.*
  FROM party_role prole,
    roles grole,
    (SELECT account.account_id,
      account.account_state_id,
      astate.name AS account_state_name,
      account.account_type_id, 
      atype.name AS account_type_name,
      account.party_role_id,
      account.active_time
    FROM account account,
      account_state astate,
      account_type atype
    WHERE  account.account_state_id = astate.account_state_id
    AND account.account_type_id  = atype.account_type_id
    AND account.account_state_id <> -1
    ) ac
  WHERE prole.role_id     = grole.role_id
  AND prole.status =1
  AND prole.party_role_id = ac.party_role_id
  ) b
ON a.party_id = b.party_id
INNER JOIN party_paper c
ON b.party_paper_id = c.paper_id
AND c.status  > 0
INNER JOIN paper_type d
ON c.paper_type = d.paper_type
LEFT JOIN agent ag on ag.party_role_id = b.party_role_id and ag.status =1
LEFT JOIN AREA dis on dis.area_code = substr(a.area_code,1,3) 
LEFT JOIN AREA subdis on subdis.area_code = substr(a.area_code,1,5) 
LEFT JOIN AREA suku on suku.area_code = a.area_code
LEFT JOIN (select carried_account,party_id from register_action where role_id = 4 and action_state_id = 10) reg on reg.party_id = a.party_id
LEFT JOIN account acc1 on acc1.account_id = reg.carried_account and acc1.account_state_id <> -1
LEFT JOIN agent ag1 on ag1.party_role_id = acc1.party_role_id and  ag1.status =1
LEFT JOIN AREA dis1 on dis1.area_code = substr(ag1.area_code,1,3) 
LEFT JOIN AREA subdis1 on subdis1.area_code = substr(ag1.area_code,1,5) 
LEFT JOIN AREA suku1 on suku1.area_code = ag1.area_code;
;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."VIEW_ACCOUNT_CANCEL_SERVICES" ("PARTY_ID", "GIVEN_NAME", "BIRTHDAY", "GENDER", "AREA_CODE", "PAPER_TYPE", "PAPER_NUMBER", "ISSUED_PLACE", "ISSUED_DATE", "BALANCE", "AVAILABLE_BALANCE", "MSISDN", "ROLE_ID", "NAME", "CURRENCY_ID", "ACCOUNT_TYPE_ID") AS 
  select t1.PARTY_ID, t1.GIVEN_NAME, t1.BIRTHDAY, t1.GENDER, t1.AREA_CODE, t1.PAPER_TYPE,
t1.PAPER_NUMBER, t1.ISSUED_PLACE, t1.ISSUED_DATE 
,t2.BALANCE, t2.AVAILABLE_BALANCE, t2.MSISDN, t2.ROLE_ID, t2.NAME, t2.CURRENCY_ID, t2.ACCOUNT_TYPE_ID
from (
select p.PARTY_ID, p.GIVEN_NAME, p.BIRTHDAY, p.GENDER, p.AREA_CODE, pp.PAPER_TYPE,
pp.PAPER_NUMBER, pp.PAPER_ID, pp.ISSUED_PLACE, pp.ISSUED_DATE
from PARTY p
JOIN PARTY_PAPER pp on p.PARTY_ID = pp.PARTY_ID 
) t1 
join (select  pr.MSISDN, pr.PARTY_ROLE_ID, pr.PARTY_ID, pr.ROLE_ID
--,acc.BALANCE, acc.AVAILABLE_BALANCE, acc.ACCOUNT_STATE_ID, acs.NAME, acc.CURRENCY_ID, acc.ACCOUNT_TYPE_ID 
,PKG_CRYPTO_UTIL.DECRYPT_BALANCE('account',acc.account_id,1) balance,PKG_CRYPTO_UTIL.DECRYPT_BALANCE('account',acc.account_id,3) AVAILABLE_BALANCE, acc.ACCOUNT_STATE_ID, acs.NAME, acc.CURRENCY_ID, acc.ACCOUNT_TYPE_ID 
from party_role pr
--join party_paper pp on pp.party_id = pr.party_id 
join party_paper pp on pp.paper_id  = pr.party_paper_id
JOIN ACCOUNT acc on pr.PARTY_ROLE_ID = acc.PARTY_ROLE_ID
JOIN ACCOUNT_STATE acs on acc.ACCOUNT_STATE_ID = acs.ACCOUNT_STATE_ID
        where pr.status = 1
        and (pr.valid_from is null or pr.valid_from <= sysdate)
        and (pr.valid_to is null or valid_to > sysdate)
        and pp.status =1
        order by pr.party_id) t2
        on t1.PARTY_ID = t2.PARTY_ID;

GRANT SELECT ON "EWALLET_V21"."VIEW_ACCOUNT_CANCEL_SERVICES" TO "VTL_SELECT";
  GRANT SELECT ON "EWALLET_V21"."VIEW_ACCOUNT_CANCEL_SERVICES" TO "ITREPORT";
;

