CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."V_ACCOUNT_STATUS" ("ACCOUNT_ID", "PAN", "CURRENCY_ID", "PARTITION_KEY", "IS_CURRENT", "ACCOUNT_TYPE_ID", "ACCOUNT_STATE_ID", "ROLE_ID", "PARTY_ID", "ROLE_NAME", "FIRST_NAME", "LAST_NAME", "GENDER", "BIRTHDAY", "PREFERRED_LANGUAGE", "USE_BANK_ACC", "MSISDN", "CURRENCY_CODE", "CURRENCY_NUM_CODE", "PAPER_TYPE", "PAPER_NUMBER", "ISSUED_DATE", "EXPIRED_DATE", "ACCOUNT_STATE_NAME", "ACCOUNT_TYPE_NAME", "PARTY_ROLE_ID", "CURRENCY_SYMBOL", "CURRENCY_DECIMAL", "BALANCE") AS 
  SELECT at.account_id,
  at.pan,
  at.CURRENCY_ID,
  at.PARTITION_KEY,
  at.IS_CURRENT,
  at.ACCOUNT_TYPE_ID,
  at.ACCOUNT_STATE_ID,
  rs.role_id,
  py.party_id ,
  rs.name role_name,
  py.first_name AS first_name,
  py.given_name  AS last_name,
  upper(py.gender) gender,
  py.birthday,
  py.PREFERRED_LANGUAGE,
  py.use_bank_acc,
  pre.msisdn,
  cy.currency_code,
  cy.currency_num_code,
  ppr.paper_type,
  ppr.paper_number,
  ppr.issued_date,
  ppr.expired_date,
  ase.name AS account_state_name,
  ate.name AS account_type_name,
  pre.party_role_id,
  cy.CURRENCY_SYMBOL,
  cy.CURRENCY_DECIMAL,
  PKG_CRYPTO_UTIL.DECRYPT_BALANCE('account',at.account_id, 3) balance
FROM account at,
  currency cy,
  account_state ase,
  account_type ate,
  party_role pre,
  roles rs,
  party py,
  party_paper ppr
WHERE at.currency_id    = cy.currency_id
AND at.account_state_id = ase.account_state_id
AND at.account_type_id  = ate.account_type_id
AND pre.role_id         = rs.role_id
AND pre.party_role_id   = at.party_role_id
AND py.party_id         = pre.party_id
AND pre.PARTY_PAPER_ID         = ppr.PAPER_ID
AND ppr.status          > 0 
AND pre.status >0
AND (pre.valid_from is null or pre.valid_from <= sysdate)
AND (pre.valid_to is null or pre.valid_to >= sysdate)
