CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."V_ACCOUNT_STATUS_FULL" ("ACCOUNT_ID", "PAN", "ACTIVE_TIME", "CURRENCY_ID", "PARTITION_KEY", "IS_CURRENT", "ACCOUNT_TYPE_ID", "ACCOUNT_STATE_ID", "ROLE_ID", "PARTY_ID", "ROLE_NAME", "FIRST_NAME", "LAST_NAME", "GENDER", "BIRTHDAY", "PREFERRED_LANGUAGE", "USE_BANK_ACC", "MSISDN", "CURRENCY_CODE", "CURRENCY_NUM_CODE", "PAPER_TYPE", "PAPER_NUMBER", "ISSUED_DATE", "EXPIRED_DATE", "ACCOUNT_STATE_NAME", "ACCOUNT_TYPE_NAME", "PARTY_ROLE_ID", "CURRENCY_SYMBOL", "CURRENCY_DECIMAL", "BALANCE") AS 
  SELECT at.account_id,
  at.pan,
  at.active_time,
  at.CURRENCY_ID,
  at.PARTITION_KEY,
  at.IS_CURRENT,
  at.ACCOUNT_TYPE_ID,
  at.ACCOUNT_STATE_ID,
  rs.role_id,
  py.party_id ,
  rs.name role_name,
  py.first_name AS first_name,
  py.given_name  AS last_name,
  upper(py.gender) gender,
