CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."V_RP_DAILY_AUDIT" ("ACCOUNT_ID", "CODE", "NAME", "BALANCE", "CREDIT", "DEBIT", "DATE_AUDIT") AS 
  SELECT account_id  
      , code
      ,name
      ,balance
      ,credit
      ,debit
      ,date_audit
FROM
(SELECT t1.account_id 
      ,t1.code
      ,t1.name
      ,t1.balance
      ,t1.credit
      ,t1.debit
      ,t1.date_audit
FROM rp_daily_audit t1
UNION ALL
SELECT vat.account_id
      ,vat.code code
      ,vat.name name
      ,vat.balance balance
      ,nvl(t1.total_credit,0) credit
      ,nvl(t1.total_debit,0) debit
      ,TRUNC(SYSDATE) date_audit
FROM V_ALL_ACCOUNT vat
    LEFT JOIN  transaction_fact_daily t1 on vat.account_id = t1.account_id
AND t1.fact_date >= TRUNC(SYSDATE) 
AND t1.fact_date < TRUNC(SYSDATE) + 1) t1;

GRANT SELECT ON "EWALLET_V21"."V_RP_DAILY_AUDIT" TO "VTL_SELECT";
  GRANT SELECT ON "EWALLET_V21"."V_RP_DAILY_AUDIT" TO "ITREPORT";
;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."V_SYS_USER" ("GIVEN_NAME", "NAME", "VALUE", "TYPE", "PARTY_ID", "ROLE_ID", "PARTY_ROLE_ID", "MSISDN", "ACCOUNT_PARENT_ID", "STATUS", "PARTY_ROLE_PARENT_ID", "PREFERRED_LANGUAGE") AS 
  SELECT P.GIVEN_NAME,P.GIVEN_NAME Name,
SU.VALUE,
CASE
    WHEN TYPE = 1 THEN  'USERNAME'
    ELSE 'MSISDN'
END TYPE,
SU.PARTY_ID,
SU.ROLE_ID,
SU.PARTY_ROLE_ID,
PR.MSISDN,
SU.ACCOUNT_PARENT_ID,
PR.STATUS,
SU.party_role_parent_id,
SU.PREFERRED_LANGUAGE
FROM SYS_USER SU
JOIN PARTY P ON P.PARTY_ID = SU.PARTY_ID
JOIN PARTY_ROLE PR ON PR.PARTY_ID = SU.PARTY_ID AND PR.PARTY_ROLE_ID = SU.PARTY_ROLE_ID
LEFT JOIN PARTY_ROLE PR_PARENT ON PR_PARENT.PARTY_ROLE_ID = SU.PARTY_ROLE_PARENT_ID
LEFT JOIN ACCOUNT AC ON AC.ACCOUNT_ID = SU.ACCOUNT_PARENT_ID AND AC.PARTY_ROLE_ID = SU.PARTY_ROLE_PARENT_ID;

GRANT SELECT ON "EWALLET_V21"."V_SYS_USER" TO "VTL_SELECT";
  GRANT SELECT ON "EWALLET_V21"."V_SYS_USER" TO "ITREPORT";
;

