  t."TRANSACTION_ID",t."FROM_ACC_ID",t."FROM_PHONE",t."FROM_NAME",t."FROM_PARTY_ROLE_ID",t."TO_ACC_ID",t."TO_PHONE",t."TO_NAME",t."TO_PARTY_ROLE_ID",t."AMOUNT",t."DISCOUNT",t."FEE",t."COMMISSION",t."TOTAL_AMOUNT",t."REVENUE_SHARED",t."CURRENCY",t."TRANS_TYPE_ID",t."TRANSACTION_STATE_ID",t."ACTION_NODE_ID",t."CARRIED_NAME",t."CARRIED_ACC_ID",t."CARRIED_CODE",t."REASON_ID",t."CONTENT",t."REASON_CONTENT",t."PARTNER_ID",t."DATE_CREATED",t."DATE_MODIFIED",t."DATE_EXPIRIED",t."DATE_DEADLINE",t."DATE_FINISHED",t."TARIFF_PLAN_ID",t."CARRIED_PHONE",
  tt.name trans_state_name
