CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."V_TRANSACTION_FULL" ("TRANSACTION_ID", "TRANSACTION_STATE_ID", "TRANSACTION_STATE", "FEE", "DISCOUNT", "COMMISSION", "FROM_NAME_UNLOCK", "PAPER_TYPE_UNLOCK", "CARRY_PAPER_TYPE", "CARRY_PAPER_NUMBER", "ACTION_ID", "PROCESS_CODE", "ACTION_NODE_ID", "ACTION_STATE_ID", "PAN", "DATE_CREATED", "LONGITUDE", "LATITUDE", "CARRIED_ACCOUNT_ID", "DATE_FINISHED", "PARTY_ROLE_ID", "MIT", "BITMAP", "ORG_AMOUNT", "FROM_CURRENCY", "AMOUNT", "EXCHANGE_RATE", "STAN", "DATE_EXPIRIED", "DATE_APPROVED", "STATUS_APPROVED", "MERCHANT_TYPE", "ROLE_ID", "SENDER_AGENT", "RECEIVER_AGENT", "PHONE", "RESPONE_CODE", "RESPONE_DES", "SERVICE_CODE", "CUS_NAME", "CUS_BIRTHDAY", "PAPER_TYPE", "PAPER_NUMBER", "ISSUED_DATE", "EXP_DATE_PAPER", "ISSUED_PLACE", "CUS_ADDRESS", "CUS_AREA", "TIN", "CUS_PHONE", "TIER", "PAYMENT_CODE", "FROM_PHONE", "TO_PHONE", "FROM_NAME", "TO_NAME", "FROM_ACCOUNT", "TO_ACCOUNT", "INQUIRER", "APPROVER", "SERVICE_INDICATOR", "TRAN_DES", "RECEIVER_AREA", "RECEIVER_ADDRESS", "CARRIED_CODE", "CARRIED_NAME", "REFERENCE_ID", "LOCK_ID", "REQUEST_ID", "FILE_NAME", "MAC", "LANG", "FROM_DATE", "TO_DATE", "EFFECT_TYPE", "TO_CURRENCY", "REQUEST_CONTENT", "RESPONSE_CONTENT", "BANK_TRANSID", "BANK_CODE", "BANK_NAME", "BRANCH_BANK", "BANK_ACCOUNT_NO", "BANK_TIME", "REQUEST_NO", "CLIENT_IP", "CUS_GENDER", "ACTION_TYPE_NAME", "ACTION_STATE_NAME", "RESPONSE_TIME", "REQUEST_TIME", "REASON_TYPE") AS 
  select t.transaction_id,
t.transaction_state_id, 
te.name  transaction_state,
ts.fee fee, 
ts.discount, 
ts.commission,

ts.FROM_NAME FROM_NAME_UNLOCK,
pt.PAPER_NAME PAPER_TYPE_UNLOCK,

pt.paper_name carry_paper_type,
pp.paper_number carry_paper_number,
ag."ACTION_ID",ag."PROCESS_CODE",ag."ACTION_NODE_ID",ag."ACTION_STATE_ID",ag."PAN",ag."DATE_CREATED",
ag."LONGITUDE",ag."LATITUDE",ag."CARRIED_ACCOUNT_ID",ag."DATE_FINISHED",ag."PARTY_ROLE_ID",ag."MIT",
ag."BITMAP",ag."ORG_AMOUNT",ag."FROM_CURRENCY",ag."AMOUNT",ag."EXCHANGE_RATE",ag."STAN",ag."DATE_EXPIRIED",ag."DATE_APPROVED",ag."STATUS_APPROVED",ag."MERCHANT_TYPE",ag."ROLE_ID",ag."SENDER_AGENT",ag."RECEIVER_AGENT",ag."PHONE",ag."RESPONE_CODE",ag."RESPONE_DES",ag."SERVICE_CODE",ag."CUS_NAME",ag."CUS_BIRTHDAY",pt.paper_name PAPER_TYPE,ag."PAPER_NUMBER",ag."ISSUED_DATE",ag."EXP_DATE_PAPER",ag."ISSUED_PLACE",ag."CUS_ADDRESS",ag."CUS_AREA",ag."TIN",ag."CUS_PHONE",ag."TIER",ag."PAYMENT_CODE",ag."FROM_PHONE",ag."TO_PHONE",ag."FROM_NAME",ag."TO_NAME",ag."FROM_ACCOUNT",ag."TO_ACCOUNT",ag."INQUIRER",ag."APPROVER",ag."SERVICE_INDICATOR",ag."TRAN_DES",ag."RECEIVER_AREA",ag."RECEIVER_ADDRESS",ag."CARRIED_CODE",ag."CARRIED_NAME",ag."REFERENCE_ID",ag."LOCK_ID",ag."REQUEST_ID",ag."FILE_NAME",ag."MAC",ag."LANG",ag."FROM_DATE",ag."TO_DATE",ag."EFFECT_TYPE",ag."TO_CURRENCY",ag."REQUEST_CONTENT",ag."RESPONSE_CONTENT",ag."BANK_TRANSID",ag."BANK_CODE",ag."BANK_NAME",ag."BRANCH_BANK",ag."BANK_ACCOUNT_NO",ag."BANK_TIME",ag."REQUEST_NO",ag."CLIENT_IP",ag."CUS_GENDER",ag."ACTION_TYPE_NAME",ag."ACTION_STATE_NAME",ag."RESPONSE_TIME",ag."REQUEST_TIME",rn.content reason_type
from transaction t
join trans_step ts on ts.transaction_id = t.transaction_id
and ts.date_created = (select max(date_created) from trans_step ts2 where ts2.transaction_id = ts.transaction_id and ts.process_code =ts2.process_code )
join action_log ag on ag.action_id = ts.action_id
left join reason rn on rn.reason_id = ag.effect_type
join trans_state te on te.trans_state_id =t.transaction_state_id
left join account ca on ca.account_id = ag.carried_account_id
left join party_role pr on pr.party_role_id = ca.party_role_id
left join party_paper pp on pp.paper_id = pr.party_paper_id
left join paper_type pt on pp.paper_type = pt.paper_type;

