CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."V_TRANSACTION_HISTORY" ("ACTION_ID", "ACCOUNT_ID", "DATE_CREATED", "BALANCE_CHANGE_ID", "DATE_FINISHED", "DEBIT", "CREDIT", "AFTER_BALANCE", "CONTENT", "TRANSACTION_STATE_ID", "FROM_PHONE", "TO_PHONE", "CARRIED_PHONE", "FROM_ACC_ID", "TO_ACC_ID", "FROM_DATE", "TO_DATE", "TRANS_TYPE_ID", "ACTION_STATE_NAME", "ACTION_TYPE_NAME", "AMOUNT", "FEE", "DISCOUNT", "PROCESS_CODE") AS 
  select 
  t.transaction_id action_id, 
  ab.account_id, 
  ab.date_created, 
  ab.balance_change_id balance_change_id, 
  t.date_finished, 
  (CASE WHEN ab.direction = -1 THEN ab.amount ELSE null END) debit, 
  (CASE WHEN ab.direction = 1 THEN ab.amount ELSE null END) credit,
   ab.after_balance, 
   ab.content, 
   t.transaction_state_id, 
   t.from_phone, 
   t.to_phone, 
   t.carried_phone carried_phone, 
   t.from_acc_id, 
   t.to_acc_id,
   '' from_date, 
   '' to_date, 
    t.trans_type_id, 
   ts.name action_state_name, -- trans_state
   tt.name action_type_name,
   t.amount amount,
   -- t.fee fee, 
   (case when t.trans_type_id = 16 then t.fee/2 else t.fee end) fee,  
   t.discount discount,
   tsp.process_code
from  transaction t 
join trans_state ts on t.transaction_state_id = ts.trans_state_id
left join  account_balance_change ab on t.transaction_id = ab.transaction_id
join trans_type tt on tt.trans_type_id = t.trans_type_id
JOIN TRANS_STEP tsp on t.transaction_id = tsp.transaction_id and tsp.action_id = (select min(action_id) from trans_step where transaction_id = t.transaction_id);

GRANT SELECT ON "EWALLET_V21"."V_TRANSACTION_HISTORY" TO "VTL_SELECT";
  GRANT SELECT ON "EWALLET_V21"."V_TRANSACTION_HISTORY" TO "ITREPORT";
;

