CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."V_TRANS_FINANCE" ("TRANSACTION_ID", "TRANS_TYPE_ID", "DATE_CREATED", "TRANSACTION_STATE", "FROM_NAME", "FROM_PHONE", "TRANS_TO_NAME", "TRANS_TO_PHONE", "TO_PAPER_TYPE", "TO_PAPER_NUMBER", "PAPER_TYPE", "PAPER_NUMBER", "ACTION_ID", "ACTION_NODE_ID", "FROM_PARTY_ROLE", "FROM_ID", "TO_PHONE", "TO_PARTY_ROLE", "TO_ID", "AMOUNT", "ORG_AMOUNT", "FEE", "TOTAL_AMOUNT", "FROM_CURRENCY", "TO_CURRENCY", "EXCHANGE_RATE", "REQUEST_REASON", "CONTENT", "REQUEST_USER", "DATE_MODIFIED", "BANK_TRANSID", "BANK_CODE", "BANK_NAME", "BRANCH_BANK", "BANK_ACCOUNTNO", "REFER_PHONE", "ACTION_STATE_ID", "APPROVED_AMOUNT", "REJECT_REASON", "CLIENT_IP", "APPROVED_USER", "REFER_ID", "SERVICE_CODE", "PROCESS_CODE", "REQUEST_APPROVED_DATE", "REQUEST_NO", "FROM_CURRENCY_ID", "TO_CURRENCY_ID", "BANK_TIME", "PARTY_ROLE_PARENT_ID") AS 
  select  t.transaction_id
 ,t.trans_type_id
 ,t.date_created
 ,te.name transaction_state
 ,t.from_name
 ,t.from_phone
  ,t.to_name trans_to_name
 ,t.to_phone trans_to_phone
  ,to_pp.paper_type to_paper_type
 ,to_pp.paper_number to_paper_number

 ,pp.paper_type paper_type
 ,pp.paper_number paper_number
 ,tf."ACTION_ID",tf."ACTION_NODE_ID",tf."FROM_PARTY_ROLE",tf."FROM_ID",tf."TO_PHONE",tf."TO_PARTY_ROLE",tf."TO_ID",tf."AMOUNT",tf."ORG_AMOUNT",tf."FEE",tf."TOTAL_AMOUNT",tf."FROM_CURRENCY",tf."TO_CURRENCY",tf."EXCHANGE_RATE",tf."REQUEST_REASON",tf."CONTENT",tf."REQUEST_USER",tf."DATE_MODIFIED",tf."BANK_TRANSID",tf."BANK_CODE",tf."BANK_NAME",tf."BRANCH_BANK",tf."BANK_ACCOUNTNO",tf."REFER_PHONE",tf."ACTION_STATE_ID",tf."APPROVED_AMOUNT",tf."REJECT_REASON",tf."CLIENT_IP",tf."APPROVED_USER",tf."REFER_ID",tf."SERVICE_CODE",tf."PROCESS_CODE",tf."REQUEST_APPROVED_DATE",tf."REQUEST_NO",tf."FROM_CURRENCY_ID",tf."TO_CURRENCY_ID",tf."BANK_TIME",tf."PARTY_ROLE_PARENT_ID"
from TRANSACTION t
left join TRANS_FINANCE tf on tf.transaction_id = t.transaction_id
join trans_state te on te.trans_state_id = t.transaction_state_id
left join party_role pr on pr.party_role_id = tf.from_party_role
left join party_paper pp on pp.paper_id = pr.party_paper_id
left join party_role to_pr on to_pr.party_role_id = tf.to_party_role
left join party_paper to_pp on to_pp.paper_id = to_pr.party_paper_id;

GRANT SELECT ON "EWALLET_V21"."V_TRANS_FINANCE" TO "VTL_SELECT";
  GRANT SELECT ON "EWALLET_V21"."V_TRANS_FINANCE" TO "ITREPORT";
;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "EWALLET_V21"."V_TRANS_FINANCE_SA" ("TRANSACTION_ID", "TRANS_TYPE_ID", "DATE_CREATED", "TRANSACTION_STATE", "FROM_NAME", "FROM_PHONE", "PAPER_TYPE", "PAPER_NUMBER", "REQUEST_USER", "ACTION_ID", "ACTION_NODE_ID", "FROM_PARTY_ROLE", "FROM_ID", "TO_PHONE", "TO_PARTY_ROLE", "TO_ID", "AMOUNT", "ORG_AMOUNT", "FEE", "TOTAL_AMOUNT", "FROM_CURRENCY", "TO_CURRENCY", "EXCHANGE_RATE", "REQUEST_REASON", "CONTENT", "DATE_MODIFIED", "BANK_TRANSID", "BANK_CODE", "BANK_NAME", "BRANCH_BANK", "BANK_ACCOUNTNO", "REFER_PHONE", "ACTION_STATE_ID", "APPROVED_AMOUNT", "REJECT_REASON", "CLIENT_IP", "APPROVED_USER", "REFER_ID", "SERVICE_CODE", "PROCESS_CODE", "REQUEST_APPROVED_DATE", "REQUEST_NO", "FROM_CURRENCY_ID", "TO_CURRENCY_ID", "BANK_TIME", "PARTY_ROLE_PARENT_ID") AS 
  select  t.transaction_id
 ,t.trans_type_id
 ,t.date_created
 ,te.name transaction_state
 
 ,a.agent_name from_name
 ,a.phone from_phone
 ,a.paper_type 
 ,a.paper_number 
 ,rq_ag.code REQUEST_USER
 ,tf."ACTION_ID",tf."ACTION_NODE_ID",tf."FROM_PARTY_ROLE",tf."FROM_ID",tf."TO_PHONE",tf."TO_PARTY_ROLE",tf."TO_ID",tf."AMOUNT",
 tf."ORG_AMOUNT",tf."FEE",tf."TOTAL_AMOUNT",tf."FROM_CURRENCY",tf."TO_CURRENCY",tf."EXCHANGE_RATE",tf."REQUEST_REASON",tf."CONTENT",
 tf."DATE_MODIFIED",tf."BANK_TRANSID",tf."BANK_CODE",tf."BANK_NAME",tf."BRANCH_BANK",tf."BANK_ACCOUNTNO",tf."REFER_PHONE",
 tf."ACTION_STATE_ID",tf."APPROVED_AMOUNT",tf."REJECT_REASON",tf."CLIENT_IP",tf."APPROVED_USER",tf."REFER_ID",tf."SERVICE_CODE",tf."PROCESS_CODE",
 tf."REQUEST_APPROVED_DATE",tf."REQUEST_NO",tf."FROM_CURRENCY_ID",tf."TO_CURRENCY_ID",tf."BANK_TIME",tf."PARTY_ROLE_PARENT_ID"
from TRANSACTION t
left join TRANS_FINANCE tf on tf.transaction_id = t.transaction_id
join trans_state te on te.trans_state_id = t.transaction_state_id
join sys_user su on (su.value = t.carried_code) 
join agent a on (su.party_role_parent_id = a.party_role_id)
left join sys_user rq_su on tf.request_user = rq_su.value
left join agent rq_ag on rq_su.party_role_parent_id = rq_ag.party_role_id;

GRANT SELECT ON "EWALLET_V21"."V_TRANS_FINANCE_SA" TO "VTL_SELECT";
;

CREATE TABLE "EWALLET_V21"."WALLET_ENTITY" 
   (	"ID" NUMBER NOT NULL ENABLE, 
	"UNIQUE_ID" VARCHAR2(40), 
	"CATEGORY" VARCHAR2(30), 
	"CODE" VARCHAR2(30), 
	"ABBREVIATION" VARCHAR2(20), 
	"NAME" VARCHAR2(100) NOT NULL ENABLE, 
	"URL" VARCHAR2(100), 
	"PATH_IMG" VARCHAR2(200), 
	"TYPE_ID" NUMBER, 
	"ACCOUNT_ID" NUMBER, 
	"TEMP_ACC_ID_IN" NUMBER, 
	"TEMP_ACC_ID_OUT" NUMBER, 
	"TOKEN" VARCHAR2(100), 
	"OPERATION_ID" VARCHAR2(40), 
	"BALANCE" NUMBER, 
	"AVAILABLE_BALANCE" NUMBER, 
	"DATE_CREATED" DATE NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(30) NOT NULL ENABLE, 
	"DATE_MODIFIED" DATE, 
	"MODIFIED_BY" VARCHAR2(30), 
	"STATUS" NUMBER NOT NULL ENABLE, 
	"NOTE" VARCHAR2(50), 
	 CONSTRAINT "WALLET_ENTITY_PK" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
