CREATE OR REPLACE PROCEDURE EWALLET_V21."GET_LST_MT" (
    i_processid   IN    INT,
    cur_lst_mt    OUT   SYS_REFCURSOR
) IS
BEGIN
    DECLARE
        v_flag NUMBER;
    BEGIN
        SELECT flag_payment_seq.NEXTVAL INTO v_flag FROM dual;
-- Giu ban ghi

        UPDATE text_mt
        SET
            process_time = sysdate,
            status = i_processid,
            flag = v_flag
        WHERE
            createtime > ( sysdate - INTERVAL '50' HOUR )
            AND status = 0
--            AND text_mt_id IN (   -- 2019-11-26: xthang: what is this for @@ ????
--                SELECT MIN(text_mt_id) text_mt_id FROM text_mt WHERE
--                    isdn IN ( SELECT isdn FROM text_mt WHERE status NOT IN ( 0, 1 ) AND process_time < sysdate - INTERVAL '1' MINUTE GROUP BY isdn )
--                    AND status = 0
--                UNION ALL
--                SELECT MIN(text_mt_id) text_mt_id FROM text_mt WHERE
--                    isdn NOT IN ( SELECT isdn FROM text_mt WHERE status <> 0 )
--                GROUP BY isdn )
            AND ROWNUM < 500;

        COMMIT;

 -- Lay ban ghi
        OPEN cur_lst_mt FOR SELECT
                                text_mt_id,
                                mt_content,
                                sender,
                                isdn
                            FROM text_mt
                            WHERE
                                createtime > ( sysdate - INTERVAL '100' HOUR )
                                AND flag = v_flag;

    END;
EXCEPTION
    WHEN OTHERS THEN  -- handles all other errors
        record_error();
END get_lst_mt;

CREATE OR REPLACE PROCEDURE EWALLET_V21.SP_RULE_ALERT AS
v_sql_check         varchar2(4000);
v_sql_param         varchar2(4000);
v_check             number;
v_count             number;
v_msg_param_cur     SYS_REFCURSOR;
v_msg_param_value   PARAM_VALUE;
v_msg_param_list    LST_PARAM_VALUE;
v_msg_param         varchar2(200);
v_msg_value         varchar2(500);
v_message           varchar2(4000);
BEGIN
    FOR i IN
        (select * from rule_alert ra 
        where ra.status = 1 
        and (valid_from <= sysdate or ra.valid_from is null)
        and (valid_to > sysdate or ra.valid_to is null)
        and (ra.last_run is null or (sysdate - ra.last_run) * 24 >= nvl(ra.frequency, 1) * decode(ra.frequency_type, 1, 1/60/60, 2, 1/60, 3, 1, 4, 24, 5, 7*24, 6, 30*24, 7, 365*24, 1))
        and (to_number(to_char(sysdate, 'hh24')) + 1 >= ra.START_WHEN or ra.START_WHEN is null)
        and (to_number(to_char(sysdate, 'hh24')) + 1 <= ra.END_WHEN or ra.END_WHEN is null)
        )
    LOOP
        BEGIN
            v_sql_check := i.script_condition;
            v_sql_param := i.script_msg_param;
            -- replace params
            FOR j IN (select * from RULE_ALERT_CONDITION where RULE_ALERT_ID = i.ID)
            LOOP
                BEGIN
                    v_sql_check := REPLACE(v_sql_check, '%' || j.PARAM || '%', NVL(to_char(j.VALUE_NUMERIC), '''' || NVL(j.VALUE_STRING, to_char(j.VALUE_DATE)) || ''''));
                    v_sql_param := REPLACE(v_sql_param, '%' || j.PARAM || '%', NVL(to_char(j.VALUE_NUMERIC), '''' || NVL(j.VALUE_STRING, to_char(j.VALUE_DATE)) || ''''));
                EXCEPTION
                    WHEN OTHERS THEN
                        record_error();
--                        DBMS_OUTPUT.put_line ('SQLERRM 1 = ' || SQLERRM);
                END;
            END LOOP;

            -- run sql
            -- set output for action
            EXECUTE IMMEDIATE v_sql_check INTO v_check;
            if (v_check <= 0) then GOTO updateRule; end if;
            -- run action
            open v_msg_param_cur for v_sql_param;
            v_msg_param_list := LST_PARAM_VALUE();
            v_count :=1;
            LOOP 
                FETCH v_msg_param_cur INTO  v_msg_param, v_msg_value;
                EXIT WHEN v_msg_param_cur%NOTFOUND;
                v_msg_param_value := PARAM_VALUE(v_msg_param, v_msg_value);
                v_msg_param_list.EXTEND;
                v_msg_param_list(v_count) := v_msg_param_value;
                v_count := v_count + 1;
            END LOOP;
            close v_msg_param_cur;
            for x in (select * from RULE_ALERT_ACTION where RULE_ALERT_ID = i.ID and STATUS = 1 and RECIPIENT is not null) 
            LOOP
                BEGIN
                    -- get alert action
                    select MESSAGE into v_message from APP_MESSAGES where LOCALE_KEY = x.CONTENT_KEY and rownum = 1;
                    for y in v_msg_param_list.first..v_msg_param_list.last loop
                        v_message := REPLACE(v_message, '%' || v_msg_param_list(y).PARAM || '%', v_msg_param_list(y).VALUE);                    
                    end loop;
                    send_sms(v_message, x.recipient, pck_common.get_sms_sender());
    --                DBMS_OUTPUT.put_line ('>>>>>> Recipient ' || x.recipient || ' | v_message = ' || v_message);
                EXCEPTION
                    WHEN OTHERS THEN
                        record_error();
                END;
            END LOOP;
            <<updateRule>> 
            -- update last_run
            update RULE_ALERT set LAST_RUN = sysdate where ID = i.ID;
        EXCEPTION
            WHEN OTHERS THEN
                record_error();
--                DBMS_OUTPUT.put_line ('SQLERRM 2 = ' || SQLERRM);
        END;
    END LOOP;
END SP_RULE_ALERT;

